for _ in range(p):
    k = int(data[pos])
    pos += 1
    for _ in range(k):
        ivs.append((int(data[pos]), int(data[pos + 1])))
        pos += 2
res = []
if ivs:
    lo = min(s for s, e in ivs)
    hi = max(e for s, e in ivs)
    busy = [False] * (hi - lo)
    for s, e in ivs:
        for t in range(s, e):
            busy[t - lo] = True
    t = 0
    while t < hi - lo:
        if not busy[t]:
            j = t
            while j < hi - lo and not busy[j]:
                j += 1
            res.append((t + lo, j + lo))
            t = j
        else:
            t += 1
print(len(res))
